import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec3, float, uniform, positionLocal, MeshStandardNodeMaterial } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-row';
  group.position.set(-1.25, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 3.4;
  const height = 0.62;

  const colorMap = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  const depthMap = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.depth.png');
  colorMap.colorSpace = THREE.SRGBColorSpace;

  const geometry = new THREE.PlaneGeometry(width, height, 64, 64);

  const parallaxOffset = uniform(vec2(0, 0));
  const displacementStrength = uniform(float(0.035));

  const colorTex = texture(colorMap, uv().add(parallaxOffset.mul(0.02)));
  const depthTex = texture(depthMap, uv());

  const material = new MeshStandardNodeMaterial();
  material.colorNode = colorTex;
  material.roughness = 0.55;
  material.metalness = 0.4;
  material.positionNode = positionLocal.add(
    vec3(0.0, 0.0, depthTex.r.sub(0.5).mul(displacementStrength))
  );

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // divider line (thin bar near bottom of row)
  const dividerGeo = new THREE.PlaneGeometry(width, 0.008, 1, 1);
  const dividerMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color('#e8ecf2'),
    transparent: true,
    opacity: 0.18,
  });
  const divider = new THREE.Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -height / 2 + 0.02, 0.001);
  group.add(divider);

  // title text
  const titleText = ctx.fontAtlas.createText({
    text: 'Features',
    font: 'display',
    weight: 600,
    size: 0.2,
    color: '#e8ecf2',
    atlasIndex: 0,
    sourceRect: [0, 0, 512, 320],
  });
  titleText.position.set(-width / 2 + 0.25, 0.06, 0.01);
  group.add(titleText);

  // meta text
  const metaText = ctx.fontAtlas.createText({
    text: 'Craft, materials & the studio process',
    font: 'text',
    weight: 400,
    size: 0.09,
    color: '#e8ecf2',
    opacity: 0.6,
    atlasIndex: 0,
    sourceRect: [0, 0, 512, 320],
  });
  metaText.position.set(-width / 2 + 0.25, -0.14, 0.01);
  group.add(metaText);

  // apply cinematic primitives (none specified)
  const primitives = (config.cinematicPrimitives || []);
  primitives.forEach((p) => {
    if (ctx.primitives[p.name]) {
      ctx.primitives[p.name](group, p.params);
    }
  });

  // interaction state
  const baseY = group.position.y;
  let hoverTl = null;
  let pressTl = null;

  function onHoverIn() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    hoverTl.to(
      displacementStrength,
      { value: 0.055, duration: 0.7, ease: 'power3.out' },
      0
    );
  }

  function onHoverOut() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
    hoverTl.to(
      displacementStrength,
      { value: 0.035, duration: 0.7, ease: 'power3.out' },
      0
    );
  }

  function onClick() {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    });
    pressTl.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.25,
      ease: 'power3.out',
    });

    if (ctx.emit) {
      ctx.emit('hub-features.select', { source: group });
    }

    if (ctx.trpc && ctx.trpc.checkout && ctx.trpc.checkout.begin) {
      ctx.trpc.checkout.begin({ itemId: 'hub-features' }).then((res) => {
        if (res && res.checkoutUrl && ctx.navigate) {
          ctx.navigate(res.checkoutUrl);
        }
      }).catch(() => {});
    }
  }

  function onFocus() {
    dividerMat.color.set('#ff2a38');
    dividerMat.opacity = 0.6;
  }

  function onBlur() {
    dividerMat.color.set('#e8ecf2');
    dividerMat.opacity = 0.18;
  }

  group.userData.handlers = {
    hoverIn: onHoverIn,
    hoverOut: onHoverOut,
    click: onClick,
    focus: onFocus,
    blur: onBlur,
  };

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    geometry.dispose();
    material.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    if (colorMap) colorMap.dispose();
    if (depthMap) depthMap.dispose();
    if (titleText && titleText.userData && titleText.userData.cleanup) {
      titleText.userData.cleanup();
    }
    if (metaText && metaText.userData && metaText.userData.cleanup) {
      metaText.userData.cleanup();
    }
  };

  return group;
}
